mapper.select:
SELECT *,c.distributor_name as customerName,w.name as warehouseName
FROM fx_import_order o
left join fx_customer_info c on o.customerid = c.id
left join fx_send_repository w on o.warehouseid = w.id


        AND product_quantity = #{productQuantity}


        AND province = #{province}


        AND city = #{city}


        AND so_id = #{soId}


        AND sku_id = #{skuId}


        AND district = #{district}


        AND address = #{address}


        AND contact = #{contact}


        AND mobile = #{mobile}


        AND is_shipped = #{isShipped}


        AND is_sales_order_generated = #{isSalesOrderGenerated}


        AND customerid = #{customerid}


        AND warehouseid = #{warehouseid}


        AND saleno = #{saleno}


        AND express_company = #{expressCompany}


        AND tracking_number = #{trackingNumber}


        AND remark = #{remark}


        AND business_affiliation = #{businessAffiliation}


        AND price = #{price}


        AND is_traceless = #{isTraceless}


        AND paying_distributor_id = #{payingDistributorId}


        AND express_company_id = #{expressCompanyId}


        AND create_time BETWEEN #{createTime[0]} AND #{createTime[1]}


ORDER BY o.id DESC
LIMIT #{offset}, #{pageSize}
